import itertools
import math

def calculate_N(a, b, c):
    """Calculates N = ((a+b+c)(ab+bc+ca)+a+b+c) / (4abc)"""
    s1 = a + b + c
    s2 = a*b + b*c + c*a
    s3 = a * b * c

    numerator = s1 * (s2 + 1)
    denominator = 4 * s3

    if denominator == 0:
        return None # Should not happen since a, b, c >= 1

    return numerator / denominator

def check_n_values(limit=10, target_n_list=[1, 2]):
    found_solutions = {n: [] for n in target_n_list}

    # Iterate through all distinct triples (a, b, c) with 1 <= a < b < c <= limit
    for triple in itertools.combinations(range(1, limit + 1), 3):
        a, b, c = triple
        N = calculate_N(a, b, c)

        # Check if N is an integer
        if N == int(N):
            n = int(N)

            # Check if this integer matches one of our targets
            if n in target_n_list:
                found_solutions[n].append(triple)

    return found_solutions

# Run the search for n=1 and n=2 up to c=10
solutions = check_n_values(limit=10, target_n_list=[1, 2])

print("--- Solutions found for N=1 ---")
if solutions[1]:
    for sol in solutions[1]:
        print(f"Triple {sol} yields N=1")
else:
    print("No solutions found for N=1 with a, b, c <= 10")

print("\n--- Solutions found for N=2 ---")
if solutions[2]:
    for sol in solutions[2]:
        print(f"Triple {sol} yields N=2")
else:
    print("No solutions found for N=2 with a, b, c <= 10")

# Also check for small integer solutions generally to see if there are unexpected patterns
print("\n--- Checking all integer solutions N <= 10 for a, b, c <= 10 ---")
all_integer_solutions = {}
for triple in itertools.combinations(range(1, 11), 3):
    a, b, c = triple
    N = calculate_N(a, b, c)
    if N == int(N):
        n = int(N)
        if n not in all_integer_solutions:
            all_integer_solutions[n] = []
        all_integer_solutions[n].append(triple)

for n, triples in sorted(all_integer_solutions.items()):
    print(f"N={n} found for {len(triples)} triples. Examples: {triples[:3]}")

def check_n_equals_2(a, b, c):
    # The equation is (a+b+c)(ab+bc+ca) + (a+b+c) = 8abc
    s = a + b + c
    q = a*b + b*c + c*a
    lhs = s * q + s
    rhs = 8 * a * b * c
    return lhs == rhs

solutions = []
for a in range(1, 11):
    for b in range(a + 1, 11):
        for c in range(b + 1, 11):
            if check_n_equals_2(a, b, c):
                solutions.append((a, b, c))
                print(f"Found solution for n=2: ({a}, {b}, {c})")

if not solutions:
    print("No solutions found for n=2 in the range 1 <= a < b < c <= 10.")
else:
    print(f"Total solutions found for n=2 in the range: {len(solutions)}")

